    ('MAJOR', 'Sedang (fitur tidak berjalan benar)'),
    ('BLOCKER', 'Berat (tidak bisa bekerja)');

CREATE TABLE bug_reports (
    id               BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    report_uuid      CHAR(36)        NOT NULL,
    tenant_id        BIGINT UNSIGNED NULL COMMENT 'Tenant pelapor; NULL = pelapor SUPERADMIN (platform)',
    reporter_id      BIGINT UNSIGNED NOT NULL,
    impersonator_id  BIGINT UNSIGNED NULL COMMENT 'Terisi bila dikirim dalam sesi impersonate (SUPERADMIN yang bertindak)',
    title            VARCHAR(120)    NOT NULL,
    description      TEXT            NOT NULL COMMENT 'Maks 4000 karakter (usecase)',
    page_path        VARCHAR(255)    NOT NULL DEFAULT '' COMMENT 'Path Console saat melapor (tanpa query/fragmen)',
    user_agent       VARCHAR(255)    NOT NULL DEFAULT '',
    app_version      VARCHAR(32)     NOT NULL DEFAULT '',
    severity_id      BIGINT UNSIGNED NOT NULL,
    status_id        BIGINT UNSIGNED NOT NULL,
    admin_note       VARCHAR(500)    NULL COMMENT 'Catatan penanganan oleh SUPERADMIN',
    emailed_at       DATETIME        NULL COMMENT 'Waktu email ke operator diserahkan ke pengirim email; NULL = belum/SMTP mati',
    created_at       DATETIME        NOT NULL DEFAULT CURRENT_TIMESTAMP,
    created_by       BIGINT UNSIGNED NULL,
    updated_at       DATETIME        NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    updated_by       BIGINT UNSIGNED NULL,
    deleted_at       DATETIME        NULL,
    deleted_by       BIGINT UNSIGNED NULL,
    is_deleted       TINYINT(1)      NOT NULL DEFAULT 0,
    UNIQUE KEY uq_bug_reports_uuid (report_uuid),
    KEY idx_bug_reports_tenant (tenant_id, created_at),
    KEY idx_bug_reports_reporter (reporter_id, created_at),
    KEY idx_bug_reports_status (status_id, created_at),
    CONSTRAINT fk_bug_reports_tenant   FOREIGN KEY (tenant_id)   REFERENCES tenants (id),
    CONSTRAINT fk_bug_reports_reporter FOREIGN KEY (reporter_id) REFERENCES users (id),
    CONSTRAINT fk_bug_reports_severity FOREIGN KEY (severity_id) REFERENCES ref_bug_report_severity (id),
    CONSTRAINT fk_bug_reports_status   FOREIGN KEY (status_id)   REFERENCES ref_bug_report_status (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='Laporan bug dari Console (migrations/0033)';

CREATE TABLE ref_data_transfer_kind (
    id          BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    code        VARCHAR(32)     NOT NULL COMMENT 'IMPORT, EXPORT',
    name        VARCHAR(128)    NOT NULL,
    created_at  DATETIME        NOT NULL DEFAULT CURRENT_TIMESTAMP,
    created_by  BIGINT UNSIGNED NULL,
    updated_at  DATETIME        NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    updated_by  BIGINT UNSIGNED NULL,
    deleted_at  DATETIME        NULL,
    deleted_by  BIGINT UNSIGNED NULL,
    is_deleted  TINYINT(1)      NOT NULL DEFAULT 0,
    UNIQUE KEY uq_ref_data_transfer_kind_code (code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='Jenis proses transfer data (migrations/0033)';

INSERT INTO ref_data_transfer_kind (code, name) VALUES ('IMPORT', 'Impor'), ('EXPORT', 'Ekspor');

CREATE TABLE ref_data_transfer_status (
    id          BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    code        VARCHAR(32)     NOT NULL COMMENT 'COMPLETED, PARTIAL, FAILED',
    name        VARCHAR(128)    NOT NULL,
    created_at  DATETIME        NOT NULL DEFAULT CURRENT_TIMESTAMP,
    created_by  BIGINT UNSIGNED NULL,
    updated_at  DATETIME        NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    updated_by  BIGINT UNSIGNED NULL,
    deleted_at  DATETIME        NULL,
    deleted_by  BIGINT UNSIGNED NULL,
    is_deleted  TINYINT(1)      NOT NULL DEFAULT 0,
    UNIQUE KEY uq_ref_data_transfer_status_code (code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='Hasil proses transfer data (migrations/0033)';

INSERT INTO ref_data_transfer_status (code, name) VALUES
    ('COMPLETED', 'Selesai'),
    ('PARTIAL', 'Sebagian berhasil'),
    ('FAILED', 'Gagal');

CREATE TABLE data_transfer_logs (
    id               BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    transfer_uuid    CHAR(36)        NOT NULL,
    tenant_id        BIGINT UNSIGNED NULL COMMENT 'Tenant pelaku; NULL = SUPERADMIN tanpa tenant (platform)',
    user_id          BIGINT UNSIGNED NOT NULL COMMENT 'Pelaku proses',
    impersonator_id  BIGINT UNSIGNED NULL COMMENT 'Terisi bila dijalankan dalam sesi impersonate',
    kind_id          BIGINT UNSIGNED NOT NULL,
    status_id        BIGINT UNSIGNED NOT NULL,
    module           VARCHAR(48)     NOT NULL COMMENT 'Modul data: devices, tenants, users, tags, ... (kata kunci tetap, divalidasi usecase)',
    format           VARCHAR(16)     NOT NULL DEFAULT 'csv',
    file_name        VARCHAR(255)    NULL COMMENT 'Nama berkas (basename tersanitasi); isi berkas TIDAK disimpan',
    total_rows       INT UNSIGNED    NOT NULL DEFAULT 0,
    success_rows     INT UNSIGNED    NOT NULL DEFAULT 0,
    failed_rows      INT UNSIGNED    NOT NULL DEFAULT 0,
    detail           VARCHAR(500)    NULL COMMENT 'Ringkasan galat/ catatan (tanpa data pribadi baris)',
    source           VARCHAR(16)     NOT NULL DEFAULT 'CLIENT' COMMENT 'SERVER = dicatat server saat memproses; CLIENT = dilaporkan Console setelah selesai',
    emailed_at       DATETIME        NULL COMMENT 'Waktu email notifikasi ke pelaku diserahkan ke pengirim email',
    created_at       DATETIME        NOT NULL DEFAULT CURRENT_TIMESTAMP,
    created_by       BIGINT UNSIGNED NULL,
    updated_at       DATETIME        NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    updated_by       BIGINT UNSIGNED NULL,
    deleted_at       DATETIME        NULL,
    deleted_by       BIGINT UNSIGNED NULL,
    is_deleted       TINYINT(1)      NOT NULL DEFAULT 0,
    UNIQUE KEY uq_data_transfer_logs_uuid (transfer_uuid),
    KEY idx_data_transfer_logs_tenant (tenant_id, created_at),
    KEY idx_data_transfer_logs_user (user_id, created_at),
    CONSTRAINT fk_dtl_tenant FOREIGN KEY (tenant_id) REFERENCES tenants (id),
    CONSTRAINT fk_dtl_user   FOREIGN KEY (user_id)   REFERENCES users (id),
    CONSTRAINT fk_dtl_kind   FOREIGN KEY (kind_id)   REFERENCES ref_data_transfer_kind (id),
    CONSTRAINT fk_dtl_status FOREIGN KEY (status_id) REFERENCES ref_data_transfer_status (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='Riwayat proses impor/ekspor data (migrations/0033)';

-- Jenis notifikasi in-app: laporan bug baru untuk operator platform (email ke operator dikirim langsung oleh usecase).
INSERT INTO ref_notification_types (code, name, description, severity_id, default_in_app, default_email, is_mandatory) VALUES
    ('BUG_REPORT', 'Laporan bug baru', 'Pengguna mengirim laporan bug dari Console.',
        (SELECT id FROM ref_notification_severity WHERE code = 'INFO'), 1, 0, 0);

-- ============================================================================
-- 16. Laporan bug: kolom harapan, tangkapan layar, notifikasi status (migrations/0034)
-- ============================================================================
-- 0034_bugreport_expected_screenshot
--
-- Laporan bug (migrations/0033) diperkaya:
--  - bug_reports.expected_behavior : "apa yang diharapkan" sebagai kolom TERPISAH dari description ("apa yang terjadi").
--    Baris lama (sebelum migrasi) mendapat '' (tidak ada data harapan).
--  - bug_report_screenshots        : satu tangkapan layar (PNG/JPEG, maks 2 MiB, divalidasi usecase: tanda tangan berkas +
--                                    decode header + dimensi) per laporan, disimpan di database agar ikut cadangan DB.
--                                    Hanya pelapor & SUPERADMIN yang dapat membacanya (lewat endpoint terautentikasi).
--  - jenis notifikasi BUG_REPORT_UPDATE : pelapor diberi tahu saat status laporannya berubah (mis. sudah ditangani).
--
-- Audit 7-kolom penuh (CLAUDE.md §2); tidak ada pengecualian.

ALTER TABLE bug_reports
    ADD COLUMN expected_behavior TEXT NOT NULL COMMENT 'Apa yang diharapkan pelapor (maks 2000 karakter, divalidasi usecase)' AFTER description;

CREATE TABLE bug_report_screenshots (
    id             BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    bug_report_id  BIGINT UNSIGNED NOT NULL,
    content_type   VARCHAR(16)     NOT NULL COMMENT 'image/png atau image/jpeg (ditentukan server dari isi berkas, bukan dari klien)',
    width          SMALLINT UNSIGNED NOT NULL,
    height         SMALLINT UNSIGNED NOT NULL,
    size_bytes     INT UNSIGNED    NOT NULL,
    sha256         CHAR(64)        NOT NULL,
    data           MEDIUMBLOB      NOT NULL,
    created_at     DATETIME        NOT NULL DEFAULT CURRENT_TIMESTAMP,
    created_by     BIGINT UNSIGNED NULL,
    updated_at     DATETIME        NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    updated_by     BIGINT UNSIGNED NULL,
    deleted_at     DATETIME        NULL,
    deleted_by     BIGINT UNSIGNED NULL,
    is_deleted     TINYINT(1)      NOT NULL DEFAULT 0,
    UNIQUE KEY uq_bug_report_screenshots_report (bug_report_id),
    CONSTRAINT fk_bug_report_screenshots_report FOREIGN KEY (bug_report_id) REFERENCES bug_reports (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='Tangkapan layar laporan bug, satu per laporan (migrations/0034)';

INSERT INTO ref_notification_types (code, name, description, severity_id, default_in_app, default_email, is_mandatory) VALUES
    ('BUG_REPORT_UPDATE', 'Status laporan bug berubah', 'Laporan bug yang Anda kirim sedang ditangani atau sudah selesai.',
        (SELECT id FROM ref_notification_severity WHERE code = 'INFO'), 1, 0, 0);

-- OPTICAL_ALERT (migrations/0036)
INSERT INTO ref_notification_types (code, name, description, severity_id, default_in_app, default_email, is_mandatory) VALUES
    ('OPTICAL_ALERT', 'Redaman optik perangkat', 'Redaman optik (RX) perangkat melewati ambang waspada atau kritis.',
        (SELECT id FROM ref_notification_severity WHERE code = 'WARNING'), 1, 0, 0);

-- 0037_device_capture
--
-- Capture sesi CWMP per perangkat untuk diagnosis kuirk firmware (mis. Fault 9002 akibat atribut xsi:type): operator
-- menyalakan capture untuk SATU perangkat selama maksimal 60 menit; selama itu setiap pesan SOAP (CPE -> ACS dan ACS -> CPE)
-- disimpan dengan nilai rahasia (password/passphrase/PSK/dst.) DISAMARKAN sebelum menyentuh database. Header HTTP
-- (Authorization, Cookie) tidak pernah disimpan.
--
--  - device_capture_switches  : saklar capture per perangkat (kedaluwarsa otomatis; satu baris per perangkat).
--  - device_session_captures  : pesan SOAP hasil capture (diekspos ke API lewat capture_uuid; PK tidak pernah keluar).
--
-- PENGECUALIAN audit 7-kolom (CLAUDE.md §2) -- disengaja, bukan default diam-diam:
--   * device_session_captures : tabel LOG volume tinggi -> audit MINIMAL, hanya created_at. Tanpa soft delete; dipangkas FISIK
--                               (dibatasi 200 pesan terbaru per perangkat + dibuang setelah 7 hari + ikut job retensi) --
--                               cleanup log sesuai kebijakan retensi eksplisit (CLAUDE.md §3).
--   * device_capture_switches : saklar sementara (bukan data master/transaksional); siapa yang menyalakan ada di
--                               enabled_by + activity_logs (CAPTURE_ENABLED/DISABLED) -> audit minimal created_at/updated_at.

CREATE TABLE device_capture_switches (
    id          BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    device_id   BIGINT UNSIGNED NOT NULL,
    expires_at  DATETIME        NOT NULL COMMENT 'Capture aktif selama expires_at > sekarang; menonaktifkan = expires_at diset ke sekarang',
    enabled_by  BIGINT UNSIGNED NULL COMMENT 'Pengguna yang menyalakan (jejak lengkap di activity_logs)',
    created_at  DATETIME        NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at  DATETIME        NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    UNIQUE KEY uq_device_capture_switches_device (device_id),
    KEY idx_device_capture_switches_expires (expires_at),
    CONSTRAINT fk_device_capture_switches_device FOREIGN KEY (device_id) REFERENCES devices (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='Saklar capture sesi CWMP per perangkat. Pengecualian audit 7-kolom (saklar sementara): lihat header migrations/0037';

CREATE TABLE device_session_captures (
    id             BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    capture_uuid   CHAR(36)        NOT NULL COMMENT 'Identifier publik di API; PK tidak pernah diekspos',
    device_id      BIGINT UNSIGNED NOT NULL,
    session_ref    CHAR(8)         NULL COMMENT '8 hex pertama SHA-256 token sesi: mengelompokkan pesan satu sesi tanpa menyimpan token',
    from_cpe       TINYINT(1)      NOT NULL COMMENT '1 = CPE -> ACS, 0 = ACS -> CPE',
    rpc_name       VARCHAR(64)     NOT NULL COMMENT 'Nama RPC/elemen SOAP (Inform, GetParameterValuesResponse, Fault, ...) atau (kosong)',
    http_status    SMALLINT UNSIGNED NULL COMMENT 'Status HTTP balasan ACS (hanya baris ACS -> CPE)',
    body           MEDIUMTEXT      NOT NULL COMMENT 'XML SOAP dengan nilai rahasia disamarkan; dipotong bila melebihi batas',
    body_bytes     INT UNSIGNED    NOT NULL COMMENT 'Ukuran asli sebelum dipotong',
    body_truncated TINYINT(1)      NOT NULL DEFAULT 0,
    created_at     DATETIME(3)     NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    UNIQUE KEY uq_device_session_captures_uuid (capture_uuid),
    KEY idx_device_session_captures_device (device_id, id),
    KEY idx_device_session_captures_created (created_at),
    CONSTRAINT fk_device_session_captures_device FOREIGN KEY (device_id) REFERENCES devices (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='Pesan SOAP hasil capture sesi CWMP (rahasia disamarkan). Pengecualian audit 7-kolom (log volume tinggi): lihat header migrations/0037';


-- 0038_device_faults
--
-- Resource "faults": catatan cwmp:Fault yang dikirim CPE sebagai jawaban RPC dari ACS (setara resource /faults GenieACS).
-- Sebelumnya fault hanya mengubah task jadi FAILED dan memicu webhook DEVICE_FAULT -- tidak ada tempat melihat "perangkat mana
-- yang sedang bermasalah dan kenapa". Satu baris = satu masalah AKTIF per (perangkat, kode fault, RPC): kejadian berulang
-- menaikkan occurrence_count dan last_seen_at, bukan menambah baris (tabel tetap kecil walau CPE mengulang fault yang sama
-- tiap sesi). Fault dibersihkan otomatis (soft delete) saat RPC yang sama berhasil pada perangkat itu, atau manual oleh
-- operator (DELETE /faults/:id).
--
-- Audit 7-kolom penuh (data transaksional kecil, bukan log volume tinggi). fault_uuid = identifier publik di API; PK tidak
-- pernah diekspos. Tanpa tenant_id: tenant dihitung dari devices.tenant_id (pola yang sama dengan tasks).
-- fault_code BUKAN ref_*: nilainya string standar dari spec Broadband Forum / kuirk vendor yang diterima apa adanya dari CPE,
-- bukan enum yang dikelola ACS.

CREATE TABLE device_faults (
    id               BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,
    fault_uuid       CHAR(36)        NOT NULL COMMENT 'Identifier publik di API; PK tidak pernah diekspos',
    device_id        BIGINT UNSIGNED NOT NULL,
    task_id          BIGINT UNSIGNED NULL COMMENT 'Task yang memicu fault terakhir (NULL bila fault datang tanpa task yang cocok)',
    rpc_method       VARCHAR(64)     NOT NULL DEFAULT '' COMMENT 'Kode ref_task_types RPC yang ditolak CPE; kosong bila tak diketahui',
    fault_code       VARCHAR(16)     NOT NULL COMMENT 'Kode fault CWMP apa adanya dari CPE (mis. 9005); string, jangan diubah penulisannya',
    fault_string     VARCHAR(1024)   NOT NULL DEFAULT '' COMMENT 'FaultString dari CPE (dipotong bila lebih panjang)',
    occurrence_count INT UNSIGNED    NOT NULL DEFAULT 1,
    first_seen_at    DATETIME(3)     NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    last_seen_at     DATETIME(3)     NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    created_at       DATETIME        NOT NULL DEFAULT CURRENT_TIMESTAMP,
    created_by       BIGINT UNSIGNED NULL,
    updated_at       DATETIME        NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    updated_by       BIGINT UNSIGNED NULL,
    deleted_at       DATETIME        NULL,
    deleted_by       BIGINT UNSIGNED NULL,
    is_deleted       TINYINT(1)      NOT NULL DEFAULT 0,
    UNIQUE KEY uq_device_faults_uuid (fault_uuid),
    KEY idx_device_faults_device_active (device_id, is_deleted, rpc_method, fault_code),
    KEY idx_device_faults_last_seen (is_deleted, last_seen_at),
    CONSTRAINT fk_device_faults_device FOREIGN KEY (device_id) REFERENCES devices (id),
    CONSTRAINT fk_device_faults_task FOREIGN KEY (task_id) REFERENCES tasks (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
  COMMENT='cwmp:Fault aktif per (perangkat, kode, RPC); kejadian berulang menaikkan occurrence_count';
